INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-first-sentences-a1-01-01', 'lesson-first-sentences-a1-01', 1, 'sentence', 'I''m a student.', 'Eu sou estudante.', '/aɪm ə ˈstuːdənt/', 'Em inglês a profissão vem com "a/an".', '[{"start":0,"end":3,"role":"subject","surface":"I''m"},{"start":4,"end":14,"role":"predicate_adj","surface":"a student."}]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"student","pos":"noun","ipa":"/ˈstuːdənt/","gloss":"estudante"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-01-02', 'lesson-first-sentences-a1-01', 2, 'sentence', 'I''m from Brazil.', 'Eu sou do Brasil.', '/aɪm frʌm brəˈzɪl/', '"From" indica origem.', '[{"start":0,"end":3,"role":"subject","surface":"I''m"},{"start":4,"end":16,"role":"adverbial","surface":"from Brazil."}]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"from","pos":"preposition","ipa":"/frʌm/","gloss":"de (origem)"},{"surface":"Brazil","pos":"proper noun","ipa":"/brəˈzɪl/","gloss":"Brasil"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-01-03', 'lesson-first-sentences-a1-01', 3, 'sentence', 'What''s your name?', 'Qual é o seu nome?', '/wʌts jʊr neɪm/', 'Pergunta básica de apresentação.', '[{"start":0,"end":6,"role":"predicate_verb","surface":"What''s"},{"start":7,"end":17,"role":"subject","surface":"your name?"}]'::jsonb, '[{"surface":"What''s","pos":"pronoun","ipa":"/wʌts/","gloss":"qual é"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"name","pos":"noun","ipa":"/neɪm/","gloss":"nome"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-01-04', 'lesson-first-sentences-a1-01', 4, 'sentence', 'Nice to meet you.', 'Prazer em te conhecer.', '/naɪs tuː miːt juː/', 'Resposta natural ao ser apresentado.', '[{"start":0,"end":4,"role":"predicate_adj","surface":"Nice"},{"start":5,"end":17,"role":"predicate_verb","surface":"to meet you."}]'::jsonb, '[{"surface":"Nice","pos":"adjective","ipa":"/naɪs/","gloss":"prazer; legal"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"meet","pos":"verb","ipa":"/miːt/","gloss":"conhecer, encontrar"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-01-05', 'lesson-first-sentences-a1-01', 5, 'sentence', 'She''s my friend.', 'Ela é minha amiga.', '/ʃiːz maɪ frɛnd/', '"Friend" serve para amigo e amiga.', '[{"start":0,"end":5,"role":"subject","surface":"She''s"},{"start":6,"end":16,"role":"predicate_adj","surface":"my friend."}]'::jsonb, '[{"surface":"She''s","pos":"pronoun","ipa":"/ʃiːz/","gloss":"ela é, ela está"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"friend","pos":"noun","ipa":"/frɛnd/","gloss":"amigo, amiga"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-01-06', 'lesson-first-sentences-a1-01', 6, 'sentence', 'He''s my brother.', 'Ele é meu irmão.', '/hiːz maɪ ˈbrʌðər/', 'Contração de "he is".', '[{"start":0,"end":4,"role":"subject","surface":"He''s"},{"start":5,"end":16,"role":"predicate_adj","surface":"my brother."}]'::jsonb, '[{"surface":"He''s","pos":"pronoun","ipa":"/hiːz/","gloss":"ele é, ele está"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"brother","pos":"noun","ipa":"/ˈbrʌðər/","gloss":"irmão"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-01-07', 'lesson-first-sentences-a1-01', 7, 'sentence', 'They''re my brothers.', 'Eles são meus irmãos.', '/ðɛr maɪ ˈbrʌðərz/', '"They''re" = "they are".', '[{"start":0,"end":7,"role":"subject","surface":"They''re"},{"start":8,"end":20,"role":"predicate_adj","surface":"my brothers."}]'::jsonb, '[{"surface":"They''re","pos":"pronoun","ipa":"/ðɛr/","gloss":"eles são, eles estão"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"brothers","pos":"noun","ipa":"/ˈbrʌðərz/","gloss":"irmãos"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-01-08', 'lesson-first-sentences-a1-01', 8, 'sentence', 'We''re at home.', 'Nós estamos em casa.', '/wɪr æt hoʊm/', '"At home" = em casa.', '[{"start":0,"end":5,"role":"subject","surface":"We''re"},{"start":6,"end":14,"role":"adverbial","surface":"at home."}]'::jsonb, '[{"surface":"We''re","pos":"pronoun","ipa":"/wɪr/","gloss":"nós estamos"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"home","pos":"noun","ipa":"/hoʊm/","gloss":"casa, lar"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-01-09', 'lesson-first-sentences-a1-01', 9, 'sentence', 'I''m thirty years old.', 'Eu tenho trinta anos.', '/aɪm ˈθɜːrti jɪrz oʊld/', 'Idade usa "to be": "I am thirty".', '[{"start":0,"end":3,"role":"subject","surface":"I''m"},{"start":4,"end":21,"role":"predicate_adj","surface":"thirty years old."}]'::jsonb, '[{"surface":"I''m","pos":"pronoun","ipa":"/aɪm/","gloss":"eu estou, eu sou"},{"surface":"thirty","pos":"numeral","ipa":"/ˈθɜːrti/","gloss":"trinta"},{"surface":"years","pos":"noun","ipa":"/jɪrz/","gloss":"anos"},{"surface":"old","pos":"adjective","ipa":"/oʊld/","gloss":"velho; de idade"}]'::jsonb, NULL, NULL),
  ('unit-first-sentences-a1-01-10', 'lesson-first-sentences-a1-01', 10, 'sentence', 'Are you tired?', 'Você está cansado?', '/ɑːr juː ˈtaɪərd/', 'Pergunta com "to be": o verbo vem antes.', '[{"start":0,"end":3,"role":"predicate_verb","surface":"Are"},{"start":4,"end":7,"role":"subject","surface":"you"},{"start":8,"end":14,"role":"predicate_adj","surface":"tired?"}]'::jsonb, '[{"surface":"Are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"tired","pos":"adjective","ipa":"/ˈtaɪərd/","gloss":"cansado"}]'::jsonb, NULL, NULL)
