INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-1000-words-a1-01-01', 'lesson-1000-words-a1-01', 1, 'word', 'mother', 'mãe', '/ˈmʌðər/', NULL, '[]'::jsonb, '[{"surface":"mother","pos":"noun","ipa":"/ˈmʌðər/","gloss":"mãe"}]'::jsonb, 'My mother is a teacher.', 'Minha mãe é professora.'),
  ('unit-1000-words-a1-01-02', 'lesson-1000-words-a1-01', 2, 'word', 'father', 'pai', '/ˈfɑːðər/', NULL, '[]'::jsonb, '[{"surface":"father","pos":"noun","ipa":"/ˈfɑːðər/","gloss":"pai"}]'::jsonb, 'My father works at home.', 'Meu pai trabalha em casa.'),
  ('unit-1000-words-a1-01-03', 'lesson-1000-words-a1-01', 3, 'word', 'brother', 'irmão', '/ˈbrʌðər/', NULL, '[]'::jsonb, '[{"surface":"brother","pos":"noun","ipa":"/ˈbrʌðər/","gloss":"irmão"}]'::jsonb, 'I have one brother.', 'Eu tenho um irmão.'),
  ('unit-1000-words-a1-01-04', 'lesson-1000-words-a1-01', 4, 'word', 'sister', 'irmã', '/ˈsɪstər/', NULL, '[]'::jsonb, '[{"surface":"sister","pos":"noun","ipa":"/ˈsɪstər/","gloss":"irmã"}]'::jsonb, 'My sister lives in Rio.', 'Minha irmã mora no Rio.'),
  ('unit-1000-words-a1-01-05', 'lesson-1000-words-a1-01', 5, 'word', 'son', 'filho', '/sʌn/', NULL, '[]'::jsonb, '[{"surface":"son","pos":"noun","ipa":"/sʌn/","gloss":"filho"}]'::jsonb, 'Their son is five.', 'O filho deles tem cinco anos.'),
  ('unit-1000-words-a1-01-06', 'lesson-1000-words-a1-01', 6, 'word', 'daughter', 'filha', '/ˈdɔːtər/', NULL, '[]'::jsonb, '[{"surface":"daughter","pos":"noun","ipa":"/ˈdɔːtər/","gloss":"filha"}]'::jsonb, 'She has a daughter.', 'Ela tem uma filha.'),
  ('unit-1000-words-a1-01-07', 'lesson-1000-words-a1-01', 7, 'word', 'husband', 'marido', '/ˈhʌzbənd/', NULL, '[]'::jsonb, '[{"surface":"husband","pos":"noun","ipa":"/ˈhʌzbənd/","gloss":"marido"}]'::jsonb, 'Her husband is from Chile.', 'O marido dela é do Chile.'),
  ('unit-1000-words-a1-01-08', 'lesson-1000-words-a1-01', 8, 'word', 'wife', 'esposa', '/waɪf/', NULL, '[]'::jsonb, '[{"surface":"wife","pos":"noun","ipa":"/waɪf/","gloss":"esposa"}]'::jsonb, 'His wife is a doctor.', 'A esposa dele é médica.'),
  ('unit-1000-words-a1-01-09', 'lesson-1000-words-a1-01', 9, 'word', 'child', 'criança', '/tʃaɪld/', NULL, '[]'::jsonb, '[{"surface":"child","pos":"noun","ipa":"/tʃaɪld/","gloss":"criança, filho"}]'::jsonb, 'Every child needs sleep.', 'Toda criança precisa dormir.'),
  ('unit-1000-words-a1-01-10', 'lesson-1000-words-a1-01', 10, 'word', 'children', 'crianças, filhos', '/ˈtʃɪldrən/', 'Plural irregular de "child".', '[]'::jsonb, '[{"surface":"children","pos":"noun","ipa":"/ˈtʃɪldrən/","gloss":"crianças, filhos"}]'::jsonb, 'The children are at school.', 'As crianças estão na escola.'),
  ('unit-1000-words-a1-01-11', 'lesson-1000-words-a1-01', 11, 'word', 'baby', 'bebê', '/ˈbeɪbi/', NULL, '[]'::jsonb, '[{"surface":"baby","pos":"noun","ipa":"/ˈbeɪbi/","gloss":"bebê"}]'::jsonb, 'The baby is sleeping.', 'O bebê está dormindo.'),
  ('unit-1000-words-a1-01-12', 'lesson-1000-words-a1-01', 12, 'word', 'parents', 'pais (pai e mãe)', '/ˈpɛrənts/', '"Parents" não é "parentes" (relatives).', '[]'::jsonb, '[{"surface":"parents","pos":"noun","ipa":"/ˈpɛrənts/","gloss":"pais (pai e mãe)"}]'::jsonb, 'My parents live near me.', 'Meus pais moram perto de mim.'),
  ('unit-1000-words-a1-01-13', 'lesson-1000-words-a1-01', 13, 'word', 'grandmother', 'avó', '/ˈɡrænmʌðər/', NULL, '[]'::jsonb, '[{"surface":"grandmother","pos":"noun","ipa":"/ˈɡrænmʌðər/","gloss":"avó"}]'::jsonb, 'My grandmother is ninety.', 'Minha avó tem noventa anos.'),
  ('unit-1000-words-a1-01-14', 'lesson-1000-words-a1-01', 14, 'word', 'grandfather', 'avô', '/ˈɡrænfɑːðər/', NULL, '[]'::jsonb, '[{"surface":"grandfather","pos":"noun","ipa":"/ˈɡrænfɑːðər/","gloss":"avô"}]'::jsonb, 'My grandfather loves soccer.', 'Meu avô adora futebol.'),
  ('unit-1000-words-a1-01-15', 'lesson-1000-words-a1-01', 15, 'word', 'uncle', 'tio', '/ˈʌŋkəl/', NULL, '[]'::jsonb, '[{"surface":"uncle","pos":"noun","ipa":"/ˈʌŋkəl/","gloss":"tio"}]'::jsonb, 'My uncle has a big dog.', 'Meu tio tem um cachorro grande.'),
  ('unit-1000-words-a1-01-16', 'lesson-1000-words-a1-01', 16, 'word', 'aunt', 'tia', '/ænt/', NULL, '[]'::jsonb, '[{"surface":"aunt","pos":"noun","ipa":"/ænt/","gloss":"tia"}]'::jsonb, 'My aunt makes great cakes.', 'Minha tia faz bolos ótimos.'),
  ('unit-1000-words-a1-01-17', 'lesson-1000-words-a1-01', 17, 'word', 'cousin', 'primo, prima', '/ˈkʌzən/', NULL, '[]'::jsonb, '[{"surface":"cousin","pos":"noun","ipa":"/ˈkʌzən/","gloss":"primo, prima"}]'::jsonb, 'My cousin is my best friend.', 'Meu primo é meu melhor amigo.'),
  ('unit-1000-words-a1-01-18', 'lesson-1000-words-a1-01', 18, 'word', 'family', 'família', '/ˈfæməli/', NULL, '[]'::jsonb, '[{"surface":"family","pos":"noun","ipa":"/ˈfæməli/","gloss":"família"}]'::jsonb, 'I have a big family.', 'Eu tenho uma família grande.'),
  ('unit-1000-words-a1-01-19', 'lesson-1000-words-a1-01', 19, 'word', 'man', 'homem', '/mæn/', NULL, '[]'::jsonb, '[{"surface":"man","pos":"noun","ipa":"/mæn/","gloss":"homem"}]'::jsonb, 'That man is my neighbor.', 'Aquele homem é meu vizinho.'),
  ('unit-1000-words-a1-01-20', 'lesson-1000-words-a1-01', 20, 'word', 'woman', 'mulher', '/ˈwʊmən/', 'Plural: "women".', '[]'::jsonb, '[{"surface":"woman","pos":"noun","ipa":"/ˈwʊmən/","gloss":"mulher"}]'::jsonb, 'The woman at the door is my aunt.', 'A mulher na porta é minha tia.')
