INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-essential-verbs-a1-01-01', 'lesson-essential-verbs-a1-01', 1, 'verb_forms', 'be was been', 'ser, estar', '/biː wɑːz bɪn/', 'Passado: "was" (I/he/she/it) e "were" (you/we/they).', '[]'::jsonb, '[{"surface":"be","pos":"verb","ipa":"/biː/","gloss":"ser, estar"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"been","pos":"verb","ipa":"/bɪn/","gloss":"sido, estado"}]'::jsonb, 'I was tired yesterday.', 'Eu estava cansado ontem.'),
  ('unit-essential-verbs-a1-01-02', 'lesson-essential-verbs-a1-01', 2, 'verb_forms', 'have had had', 'ter', '/hæv hæd hæd/', NULL, '[]'::jsonb, '[{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"}]'::jsonb, 'We had a great time.', 'A gente se divertiu muito.'),
  ('unit-essential-verbs-a1-01-03', 'lesson-essential-verbs-a1-01', 3, 'verb_forms', 'do did done', 'fazer', '/duː dɪd dʌn/', NULL, '[]'::jsonb, '[{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"done","pos":"adjective","ipa":"/dʌn/","gloss":"pronto, feito"}]'::jsonb, 'Did you do your homework?', 'Você fez sua lição?'),
  ('unit-essential-verbs-a1-01-04', 'lesson-essential-verbs-a1-01', 4, 'verb_forms', 'say said said', 'dizer', '/seɪ sɛd sɛd/', NULL, '[]'::jsonb, '[{"surface":"say","pos":"verb","ipa":"/seɪ/","gloss":"dizer"},{"surface":"said","pos":"verb","ipa":"/sɛd/","gloss":"disse, dito"},{"surface":"said","pos":"verb","ipa":"/sɛd/","gloss":"disse, dito"}]'::jsonb, 'She said yes.', 'Ela disse sim.'),
  ('unit-essential-verbs-a1-01-05', 'lesson-essential-verbs-a1-01', 5, 'verb_forms', 'go went gone', 'ir', '/ɡoʊ wɛnt ɡɔːn/', NULL, '[]'::jsonb, '[{"surface":"go","pos":"verb","ipa":"/ɡoʊ/","gloss":"ir"},{"surface":"went","pos":"verb","ipa":"/wɛnt/","gloss":"foi (passado de go)"},{"surface":"gone","pos":"verb","ipa":"/ɡɔːn/","gloss":"ido (particípio de go)"}]'::jsonb, 'They went home early.', 'Eles foram para casa cedo.'),
  ('unit-essential-verbs-a1-01-06', 'lesson-essential-verbs-a1-01', 6, 'verb_forms', 'get got gotten', 'conseguir, pegar, ficar', '/ɡɛt ɡɑːt ˈɡɑːtən/', 'No inglês britânico o particípio é "got".', '[]'::jsonb, '[{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"got","pos":"verb","ipa":"/ɡɑːt/","gloss":"conseguiu, pegou"},{"surface":"gotten","pos":"verb","ipa":"/ˈɡɑːtən/","gloss":"conseguido"}]'::jsonb, 'I got a new job.', 'Eu consegui um emprego novo.'),
  ('unit-essential-verbs-a1-01-07', 'lesson-essential-verbs-a1-01', 7, 'verb_forms', 'make made made', 'fazer (criar)', '/meɪk meɪd meɪd/', NULL, '[]'::jsonb, '[{"surface":"make","pos":"verb","ipa":"/meɪk/","gloss":"fazer; conseguir ir (make it)"},{"surface":"made","pos":"verb","ipa":"/meɪd/","gloss":"fez, feito"},{"surface":"made","pos":"verb","ipa":"/meɪd/","gloss":"fez, feito"}]'::jsonb, 'She made a cake.', 'Ela fez um bolo.'),
  ('unit-essential-verbs-a1-01-08', 'lesson-essential-verbs-a1-01', 8, 'verb_forms', 'know knew known', 'saber, conhecer', '/noʊ nuː noʊn/', NULL, '[]'::jsonb, '[{"surface":"know","pos":"verb","ipa":"/noʊ/","gloss":"saber"},{"surface":"knew","pos":"verb","ipa":"/nuː/","gloss":"sabia, conheceu"},{"surface":"known","pos":"verb","ipa":"/noʊn/","gloss":"sabido, conhecido"}]'::jsonb, 'I knew the answer.', 'Eu sabia a resposta.'),
  ('unit-essential-verbs-a1-01-09', 'lesson-essential-verbs-a1-01', 9, 'verb_forms', 'think thought thought', 'pensar, achar', '/θɪŋk θɔːt θɔːt/', NULL, '[]'::jsonb, '[{"surface":"think","pos":"verb","ipa":"/θɪŋk/","gloss":"achar, pensar"},{"surface":"thought","pos":"verb","ipa":"/θɔːt/","gloss":"pensou, pensado"},{"surface":"thought","pos":"verb","ipa":"/θɔːt/","gloss":"pensou, pensado"}]'::jsonb, 'I thought you were at work.', 'Achei que você estava no trabalho.'),
  ('unit-essential-verbs-a1-01-10', 'lesson-essential-verbs-a1-01', 10, 'verb_forms', 'take took taken', 'pegar, levar', '/teɪk tʊk ˈteɪkən/', NULL, '[]'::jsonb, '[{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"took","pos":"verb","ipa":"/tʊk/","gloss":"pegou, levou"},{"surface":"taken","pos":"verb","ipa":"/ˈteɪkən/","gloss":"pegado, levado"}]'::jsonb, 'He took the bus.', 'Ele pegou o ônibus.')
